local UIModule = CS.Engine.UI.UIModule
local KTool = CS.Engine.Lib.KTool
------------ import ------------
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local RegionQuestMgr = import('Game.UI.FightReady.UIMainChapter.RegionQuestMgr')
local FontStyleButton = CS.Game.Native.Common.FontStyleButton
local cardComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)


--- from: Assets/BundleResources/Prefabs/Action/ActionTeamDestoryDialog.prefab > name: PlayerGroup
---@class UIActionTeamDestoryNode
---@field Env                           	UIActionTeamDestoryNode                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field CommonVoiceChatShow           	UnityEngine.RectTransform               
---@field BtnKickOut                    	UnityEngine.RectTransform               
---@field ImgLoad                       	UnityEngine.RectTransform               
---@field TxtNum                        	UnityEngine.RectTransform               
---@field LoadingGroup                  	UnityEngine.RectTransform               
---@field ReadyFinishGroup              	UnityEngine.RectTransform               
---@field BtnView                       	UnityEngine.RectTransform               
