local UIActionTeamDestoryNode = Class("UIActionTeamDestoryNode")
function UIActionTeamDestoryNode:__init()
    self:CleanProperties()
end

function UIActionTeamDestoryNode:__delete()
    self:CleanProperties()
end

function UIActionTeamDestoryNode:CleanProperties()
    self._isOwn = false                  --是否自己
    self._commonPlayerHeadNodeScr = nil

    self._data = nil
    self._cb = nil
    self._isHouseOwner = false          -- 是否是房主
end

function UIActionTeamDestoryNode:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end

    SetButtonAction(self.BtnView, Bind(self, self.OnBtnTeam))
    SetButtonAction(self.BtnAddMember, Bind(self, self.OnBtnTeam))
    SetButtonAction(self.BtnKickOut, Bind(self, self.OnKickOut))
end

function UIActionTeamDestoryNode:Start()
end

function UIActionTeamDestoryNode:Refresh(data, isOwn, isHouseOwner, cb, clickHeadCb, useVoiceRoom)
    if not data then
        return
    end
    self._isOwn = isOwn
    self._data = data
    self._cb = cb
    self._clickHeadCb = clickHeadCb
    self._isHouseOwner = isHouseOwner

    self:FillSelf(useVoiceRoom)
end

function UIActionTeamDestoryNode:FillSelf(useVoiceRoom)
    CfUtils.SetActive(self.controller.gameObject.transform:Find("ImgCaptain"), self._isHouseOwner)

    self:FillRoleInfo()
    self:FillTeamMembers()

    KTool.SetActive(self.BtnKickOut, not self._isHouseOwner and not self._isOwn)    -- 房客显示踢人按钮

    -- 麦克风节点
    KTool.SetActive(self.CommonVoiceChatShow, useVoiceRoom)
    if useVoiceRoom then
        local playerId = checkNumber(self._data.playerInfo.playerId)
        local lb = GetLuaBehaviour(self.CommonVoiceChatShow.gameObject, "Game.Behaviours.CommonMicStateNode")
        lb.Env:SetPlayerId(playerId)
    end
end

function UIActionTeamDestoryNode:FillRoleInfo()
    if self._commonPlayerHeadNodeScr then        
        local avatar = self._data.playerInfo.avatar
        local avatarFrame = self._data.playerInfo.avatarFrame
        self._commonPlayerHeadNodeScr:FreshAvatarFrame(avatar, avatarFrame)
        self._commonPlayerHeadNodeScr:SetCallBack(self._clickHeadCb)
    end

    CfUtils.FillText(self.TxtLv, "Lv"..self._data.playerInfo.level)
    CfUtils.FillText(self.TxtPlayerName, self._data.playerInfo.name)

    local pow = 0
    if self._data.mainTeamSet then
        if self._isOwn then
            pow = self._data.mainTeamSet.totalCombatVal
        else
            CfUtils.SetActive(self.TxtPower, true)
            pow = checkNumber(self._data.mainTeamSet.totalCombatVal)
        end
    end
    CfUtils.FillText(self.TxtPower, pow)
end

function UIActionTeamDestoryNode:FillTeamMembers()
    local hasTeamMember = self:HasTeamMember()

    CfUtils.SetActive(self.BtnAddMember, not hasTeamMember and self._isOwn)
    CfUtils.SetActive(self.BtnView, hasTeamMember)

    if not hasTeamMember then
        for i = 1, 3, 1 do
            local go = self.TeamMemberGroup.transform:Find("Member"..i)
            if isNull(go) then
                go = KTool.Instantiate(self.TeamMemberGroup.gameObject, self.TeamMemberGroup.transform:Find("Member1").gameObject)
                go.name = "Member"..i
            end
            if isNotNull(go) then
                KTool.SetActive(go, true)
                if self._isOwn then
                    SetButtonAction(go.transform:Find("ImgBg").gameObject, Bind(self, self.OnBtnTeam))
                end
                CfUtils.SetActive(go.transform:Find("ImgBg/ImgIconOthers"), not self._isOwn)
                CfUtils.SetActive(go.transform:Find("ImgBg/ImgIconMyself"), self._isOwn)
                CfUtils.SetActive(go.transform:Find("CommonSmallHeadNode"), false)
            end
        end
    else
        local t = checkTable(self._data.mainTeamSet.cardsInfo)
        for k, v in pairs(t) do
            local go = self.TeamMemberGroup.transform:Find("Member"..k)
            if isNull(go) then
                go = KTool.Instantiate(self.TeamMemberGroup.gameObject, self.TeamMemberGroup.transform:Find("Member1").gameObject)
                go.name = "Member"..k
            end
            if isNotNull(go) then
                KTool.SetActive(go, true)
                -- 背景绑定点击事件
                local isHas = checkNumber(v.refId) > 0
                CfUtils.SetActive(go.transform:Find("ImgBg/ImgIconOthers"), not isHas and not self._isOwn)
                CfUtils.SetActive(go.transform:Find("ImgBg/ImgIconMyself"), not isHas and self._isOwn)
                CfUtils.SetActive(go.transform:Find("CommonSmallHeadNode"), isHas)
                if not isHas then
                    SetButtonAction(go.transform:Find("ImgBg").gameObject, Bind(self, self.OnBtnTeam))
                else
                    CfUtils.RefeshCommonSmallHeroGo(go.transform:Find("CommonSmallHeadNode"), v.cardInfo, Vector3(0.4, 0.4, 0), function()
                        self:OnBtnTeam()
                    end)
                end
            end
        end
    end
end

function UIActionTeamDestoryNode:FillReadyInfo(state)
    local hasTeamMember = self:HasTeamMember()
    local isReady = checkNumber(state) == 1
    if self._isHouseOwner then
        if self._isOwn then
            CfUtils.SetActive(self.ReadyFinishGroup, hasTeamMember)
            CfUtils.SetActive(self.TxtPreparing, false)
        else
            CfUtils.SetActive(self.ReadyFinishGroup, hasTeamMember)
            CfUtils.SetActive(self.TxtPreparing, not hasTeamMember)
        end
    else
        if self._isOwn then
            CfUtils.SetActive(self.ReadyFinishGroup, hasTeamMember and isReady or false)
            CfUtils.SetActive(self.TxtPreparing, false)
        else
            CfUtils.SetActive(self.ReadyFinishGroup, isReady)
            CfUtils.SetActive(self.TxtPreparing, not isReady)
        end
    end
end

function UIActionTeamDestoryNode:FillLoad()
    CfUtils.SetActive(self.ReadyFinishGroup, false)
end

function UIActionTeamDestoryNode:OnBtnTeam()
    if self._cb then
        self._cb()
    end
end

--- 踢人
function UIActionTeamDestoryNode:OnKickOut()
    RegionQuestMgr:GetInstance():KickOutReq()
end

function UIActionTeamDestoryNode:HasTeamMember()
    if not self._data.mainTeamSet then
        return false
    end

    local t = checkTable(self._data.mainTeamSet.cardsInfo)
    return table.count(t) > 0
end

function UIActionTeamDestoryNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionTeamDestoryNode